when CLIENT_ACCEPTED {
  if { [active_members http_pool] >= 2 } {
    pool http_pool
  }
}

when HTTP_REQUEST {
  if { [active_members http_pool] >= 2 } {
    pool http_pool
  }
}

when HTTP_REQUEST {
  set members [active_members -list http_pool]
  log local0. "Active members are: $members"
}
